// Glues the modules in js/ into one plain script: js/oche.bundle.js.
//
// Why: the browser does not load modules (`type="module"`) from a page opened
// straight from disk (file://); it blocks them like cross-origin requests. Without this,
// double-clicking index.html gave nothing working, not even the board or the keypad.
// A page opened from a file therefore takes this bundle; from a server, the plain modules.
//
// No dependencies and no real parser: the modules stick to simple forms
// (`import { a, b } from './x.js'`, `import * as x from './x.js'`,
// `export function`, `export const`), and only those are supported here.
//
//   node scripts/bundle.js          writes the bundle
//   node scripts/bundle.js --check  checks only whether the bundle is up to date

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const JS_DIR = path.join(ROOT, 'public', 'js');
const ENTRY = 'app';
export const BUNDLE_PATH = path.join(JS_DIR, 'oche.bundle.js');

const IMPORT_RE = /^import\s+([\s\S]*?)\s+from\s+'\.\/([\w-]+)\.js';[ \t]*\r?\n?/gm;
const EXPORT_RE = /^export\s+(?:async\s+)?(?:function\*?|const|let|class)\s+([A-Za-z_$][\w$]*)/gm;

function readModule(name) {
  return fs.readFileSync(path.join(JS_DIR, `${name}.js`), 'utf8').replace(/\r\n/g, '\n');
}

/** Modules in dependency order: each after the ones it imports from. */
function moduleOrder(entry) {
  const order = [];
  const seen = new Set();
  const visit = (name) => {
    if (seen.has(name)) return;
    seen.add(name);
    for (const match of readModule(name).matchAll(IMPORT_RE)) visit(match[2]);
    order.push(name);
  };
  visit(entry);
  return order;
}

function importToConst(clause, from) {
  const namespace = clause.match(/^\*\s+as\s+([\w$]+)$/);
  if (namespace) return `const ${namespace[1]} = __modules['${from}'];`;

  const named = clause.match(/^\{([\s\S]*)\}$/);
  if (!named) throw new Error(`Unsupported import from ./${from}.js: ${clause}`);
  const bindings = named[1]
    .split(',')
    .map((part) => part.trim())
    .filter(Boolean)
    .map((part) => part.replace(/^([\w$]+)\s+as\s+([\w$]+)$/, '$1: $2'));
  return `const { ${bindings.join(', ')} } = __modules['${from}'];`;
}

function wrapModule(name) {
  const exported = [];
  const body = readModule(name)
    .replace(IMPORT_RE, (_, clause, from) => `${importToConst(clause.trim(), from)}\n`)
    .replace(EXPORT_RE, (match, id) => {
      exported.push(id);
      return match.replace(/^export\s+/, '');
    });

  if (/^export\s/m.test(body)) throw new Error(`Unsupported export in ${name}.js`);

  return `// --- js/${name}.js ---\n`
    + `__modules['${name}'] = (function () {\n${body.trimEnd()}\n\nreturn { ${exported.join(', ')} };\n})();\n`;
}

export function buildBundle() {
  const modules = moduleOrder(ENTRY).map(wrapModule).join('\n');
  return '// Generated by scripts/bundle.js. Do not edit by hand.\n'
    + '// The app for a page opened straight from disk (file://).\n'
    + "(function () {\n'use strict';\nconst __modules = {};\n\n"
    + modules
    + '})();\n';
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const fresh = buildBundle();
  if (process.argv.includes('--check')) {
    const current = fs.existsSync(BUNDLE_PATH) ? fs.readFileSync(BUNDLE_PATH, 'utf8').replace(/\r\n/g, '\n') : '';
    if (current !== fresh) {
      console.error('js/oche.bundle.js is out of date; run: npm run bundle');
      process.exit(1);
    }
    console.log('js/oche.bundle.js is up to date');
  } else {
    fs.writeFileSync(BUNDLE_PATH, fresh);
    console.log(`Wrote ${path.relative(ROOT, BUNDLE_PATH)}`);
  }
}
